const item = $input.item.json;
const tenant = item.tenant || {};
const sender = item.sender || {};
const msg = item.message || {};

const text = msg.text || item.original_message || item.message || '';
const number = sender.number || tenant.number || item.number || '521234567890';
const senderType = sender.type || item.sender_type || 'client';

return {
  message: text,
  number: number,
  sender_type: senderType,
  tenant: tenant,
  sender: sender
};

const rawOutput  = $input.item.json.output || $input.item.json.text || '{}';
const triggerData = $('Code - Normalize Inbound Appointment Request').item.json;
let parsed = {};
try {
  const jsonMatch = rawOutput.match(/\{[\s\S]*\}/);
  if (jsonMatch) parsed = JSON.parse(jsonMatch[0]);
} catch(e) {
  parsed = { created_by: triggerData.sender_type, title: 'Cita sin título', appointment_date: null, status: 'scheduled', is_valid: false };
}
return {
  created_by:       parsed.created_by       || triggerData.sender_type,
  title:            parsed.title            || 'Cita sin título especificado',
  appointment_date: parsed.appointment_date || null,
  status:           parsed.status           || 'scheduled',
  is_valid:         parsed.is_valid !== false && !!parsed.appointment_date,
  sender_number:    triggerData.number,
  tenant:           triggerData.tenant,
  sender:           triggerData.sender
};

const apptData   = $('Code - Parse Appointment Details').item.json;
const clientData = $input.item.json;
return {
  client_id:        clientData ? clientData.id : null,
  tenant_id:        apptData.tenant ? apptData.tenant.id : (clientData ? clientData.tenant_id : null),
  title:            apptData.title,
  appointment_date: apptData.appointment_date,
  status:           apptData.status || 'scheduled',
  created_by:       apptData.created_by || 'client',
  sender_number:    apptData.sender_number,
  client_name:      clientData ? clientData.name : 'Cliente',
  tenant:           apptData.tenant
};

const apptRecord = $input.item.json;
const insertData = $('Code - Prepare Appointment Insert Payload').item.json;
const apptDate   = new Date(apptRecord.appointment_date || insertData.appointment_date);

const formattedDate = apptDate.toLocaleDateString('es-MX', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});
const formattedTime = apptDate.toLocaleTimeString('es-MX', {
  hour: '2-digit', minute: '2-digit', hour12: true
});

const startDateIso = apptDate.toISOString().replace(/-|:|\.\d+/g, '');
const endDate      = new Date(apptDate.getTime() + 60 * 60 * 1000);
const endDateIso   = endDate.toISOString().replace(/-|:|\.\d+/g, '');
const gcalUrl      = `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent(apptRecord.title || insertData.title)}&dates=${startDateIso}/${endDateIso}&details=${encodeURIComponent('Cita agendada via WhatsApp')}`;

const confirmationMsg = `📅 *¡CITA AGENDADA EXITOSAMENTE!*\n\n` +
`📌 *Asunto:* ${apptRecord.title || insertData.title}\n` +
`🗓️ *Fecha:* ${formattedDate}\n` +
`⏰ *Hora:* ${formattedTime}\n` +
`🔖 *Estado:* Agendada\n\n` +
`📲 *Añadir a Google Calendar:*\n${gcalUrl}\n\n` +
`_Si deseas cancelar o reprogramar, indícalo por este chat._`;

const buttons = [
  { id: "ver citas", title: "📅 Mis Citas" },
  { id: "ver inventario", title: "🛍️ Ver Catálogo" },
  { id: "menu", title: "🏠 Menú Principal" }
];

return {
  wa_number:       insertData.sender_number,
  wa_message:      confirmationMsg,
  buttons:         buttons,
  appointment_id:  apptRecord.id,
  client_name:     insertData.client_name,
  formatted_date:  `${formattedDate} a las ${formattedTime}`,
  title:           apptRecord.title || insertData.title,
  created_by:      insertData.created_by,
  tenant:          insertData.tenant,
  phone_number_id: (insertData.tenant ? insertData.tenant.whatsapp_phone_number_id : '10023456789'),
  access_token:    (insertData.tenant ? insertData.tenant.whatsapp_access_token : 'EAAG_DEMO_TOKEN')
};

const item = $input.item.json;
const adminMsg = `🔔 *NUEVA CITA AGENDADA POR CLIENTE*\n\n` +
`👤 *Cliente:* ${item.client_name} (${item.wa_number})\n` +
`📌 *Asunto:* ${item.title}\n` +
`🗓️ *Fecha:* ${item.formatted_date}\n` +
`🔖 *ID Cita:* "${item.appointment_id || 'N/A'}"`;

const buttons = [
  { id: "ver citas", title: "📅 Ver Agenda Hoy" },
  { id: "tareas", title: "📋 Ver Pendientes" }
];

return {
  wa_number: (item.tenant ? item.tenant.number : '521234567890'),
  wa_message: adminMsg,
  buttons: buttons,
  phone_number_id: item.phone_number_id,
  access_token: item.access_token
};

const apptData = $('Code - Parse Appointment Details').item.json;
const errorMsg = `⚠️ *No pude entender la fecha de tu cita.*\n\n` +
`Por favor especifica el día y la hora. Ejemplo:\n` +
`_"Quiero una cita para el próximo lunes a las 4pm para asesoría"_`;

return {
  wa_number:       apptData.sender_number,
  wa_message:      errorMsg,
  buttons:         [{ id: "ver citas", title: "📅 Ver Disponibilidad" }, { id: "menu", title: "🏠 Menú" }],
  phone_number_id: (apptData.tenant ? apptData.tenant.whatsapp_phone_number_id : '10023456789'),
  access_token:    (apptData.tenant ? apptData.tenant.whatsapp_access_token : 'EAAG_DEMO_TOKEN')
};
